		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			cfg, data := testPaths(t)
			var out, errOut bytes.Buffer
			if err := Execute([]string{"--config", cfg, "init", data, "--remote", ""}, &out, &errOut); err != nil {
				t.Fatal(err)
