	got := contacts[0]
	if got.Source != "telecrawl" || got.Name != "Ada" || len(got.Phones) != 2 {
		t.Fatalf("mapped contact = %#v", got)
	}
	if !got.Phones[0].Primary || got.Phones[1].Primary {
