import { spawnSync } from "node:child_process";
import test from "node:test";

const generator = fs.readFileSync(new URL("./generate-llms.mjs", import.meta.url), "utf8");

function generate(t, { title, description }) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "clawdex-llms-"));
  t.after(() => fs.rmSync(root, { recursive: true, force: true }));
  fs.mkdirSync(path.join(root, "scripts"));
  fs.writeFileSync(path.join(root, "scripts/generate-llms.mjs"), generator);
  fs.writeFileSync(path.join(root, "CNAME"), "clawdex.sh\n");
  fs.writeFileSync(
    path.join(root, "index.html"),
    `<title>${title}</title><meta name="description" content="${description}">`,
  );
  const result = spawnSync(process.execPath, ["scripts/generate-llms.mjs"], {
    cwd: root,
    encoding: "utf8",
  });
  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.stdout, "wrote llms.txt\n");
  const output = fs.readFileSync(path.join(root, "llms.txt"), "utf8");
  return output;
}

const fixtures = [
  ["current metadata", "Clawdex — local-first contact index", "Personal contact index backed by markdown and private Git.", "Clawdex — local-first contact index", "Personal contact index backed by markdown and private Git."],
  ["known entities", "Clawdex &mdash; contacts", "Local&nbsp;first &amp; private", "Clawdex - contacts", "Local first & private"],
  ["nested entities", "Clawdex &amp;mdash; contacts", "Local&amp;nbsp;first", "Clawdex &mdash; contacts", "Local&nbsp;first"],
  ["markup-like text", "Clawdex <contacts>", "Use <script and <notes> literally", "Clawdex <contacts>", "Use <script and <notes> literally"],
  ["whitespace", "  Clawdex \n\t contacts  ", "  Local \n\t first  ", "Clawdex contacts", "Local first"],
];

for (const [name, title, description, expectedTitle, expectedDescription] of fixtures) {
  test(`generate-llms: ${name}`, (t) => {
    const output = generate(t, { title, description });
    assert.match(output, new RegExp(`^${escapeRegex(expectedDescription)}$`, "m"));
    assert.match(output, new RegExp(`^- ${escapeRegex(expectedTitle)}: https://clawdex\\.sh/$`, "m"));
  });
}

function escapeRegex(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

name: ClawSweeper Dispatch

on:
  issues:
    types: [opened, reopened, edited, labeled, unlabeled]
  issue_comment:
    types: [created, edited]
  pull_request_target: # zizmor: ignore[dangerous-triggers] maintainer-owned external dispatch; no checkout or untrusted PR code execution
    types: [opened, reopened, synchronize, ready_for_review, edited, labeled, unlabeled]

permissions:
  contents: read

concurrency:
  group: clawsweeper-dispatch-${{ github.repository }}-${{ github.event_name }}-${{ github.event.comment.id || github.event.issue.number || github.event.pull_request.number || github.run_id }}-${{ endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled') && github.actor || 'dispatchable' }}
  cancel-in-progress: ${{ github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review' }}

jobs:
  dispatch:
    runs-on: ubuntu-latest
    # id-token proves this repository, event, branch, and run to the queue.
    # The job never checks out or executes pull request code.
    permissions:
      contents: read
      id-token: write
    if: ${{ !(endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled')) }}
    env:
      SUPERSEDES_IN_PROGRESS: ${{ (github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review') && 'true' || 'false' }}
    steps:
      - name: Debounce bursty metadata events
        if: ${{ github.event.action == 'labeled' || github.event.action == 'unlabeled' }}
        run: sleep 20

      - name: Pre-filter ClawSweeper comment
        id: comment_filter
        if: ${{ github.event_name == 'issue_comment' }}
        env:
          COMMENT_BODY: ${{ github.event.comment.body }}
        run: |
          set -euo pipefail
          if [[ "$COMMENT_BODY" == *"<!-- clawsweeper-maintainer-opt-in:"* ]]; then
            echo "is_command=false" >> "$GITHUB_OUTPUT"
            exit 0
          fi
          if grep -Eiq '(^|[[:space:]])@(clawsweeper|openclaw-clawsweeper)\b(\[bot\])?|(^|[[:space:]])/(clawsweeper|review|re-review|rerun([[:space:]]+|-)?review|status|explain|fix|build|implement|create([[:space:]]+|-)?pr|fix([[:space:]]+|-)?issue|autofix|auto([[:space:]]+|-)?fix|automerge|auto([[:space:]]+|-)?merge|approve|stop|autoclose)\b' <<< "$COMMENT_BODY"; then
            echo "is_command=true" >> "$GITHUB_OUTPUT"
          else
            echo "is_command=false" >> "$GITHUB_OUTPUT"
          fi

      - name: Dispatch exact ClawSweeper review
        if: ${{ github.event_name != 'issue_comment' }}
        env:
          TARGET_REPO: ${{ github.repository }}
          TARGET_BRANCH: ${{ github.event.repository.default_branch }}
          ITEM_NUMBER: ${{ github.event.issue.number || github.event.pull_request.number }}
          ITEM_KIND: ${{ github.event_name == 'pull_request_target' && 'pull_request' || 'issue' }}
          SOURCE_EVENT: ${{ github.event_name }}
          SOURCE_ACTION: ${{ github.event.action }}
          TARGET_DISPATCH_URL: https://clawsweeper.openclaw.ai/github/target-dispatch
        run: |
          set -euo pipefail
          source_identity_json="$(node <<'NODE'
          const crypto = require("node:crypto");
          const fs = require("node:fs");
          const event = JSON.parse(fs.readFileSync(process.env.GITHUB_EVENT_PATH, "utf8"));
          const pullRequest = event.pull_request && typeof event.pull_request === "object"
            ? event.pull_request
            : {};
          const issue = event.issue && typeof event.issue === "object" ? event.issue : {};
          const source = process.env.ITEM_KIND === "pull_request" ? pullRequest : issue;
          const headSha = String(pullRequest.head?.sha || "").trim().toLowerCase();
          const baseSha = String(pullRequest.base?.sha || "").trim().toLowerCase();
          const updatedAt = String(pullRequest.updated_at || "").trim();
          const queueClaim = {};
          const result = { queue_claim: queueClaim };
          const sourceUpdatedAt = String(source.updated_at || "").trim();
          if (sourceUpdatedAt && Number.isFinite(Date.parse(sourceUpdatedAt))) {
            queueClaim.source_updated_at = sourceUpdatedAt;
          }
          if (
            typeof source.title === "string" &&
            (source.body === null || typeof source.body === "string") &&
            typeof source.locked === "boolean" &&
            Array.isArray(source.labels)
          ) {
            const labels = [
              ...new Set(
                source.labels
                  .map((label) => String(label?.name || "").trim().toLowerCase())
                  .filter((label) => {
                    if (!label) return false;
                    if (label === "proof: override") return true;
                    if (/^(?:status|rating|proof|merge-risk|impact|issue-rating):/.test(label)) return false;
                    if (/^p[0-3]$/.test(label)) return false;
                    if ([
                      "maturity:stable",
                      "feature: ✨ showcase",
                      "good first issue",
                      "mantis: telegram-visible-proof",
                      "proof: telegram-e2e",
                      "triage: needs-real-behavior-proof",
                      "clawsweeper-recovery-stuck",
                      "no-stale",
                      "stale",
                    ].includes(label)) return false;
                    return !label.startsWith("clawsweeper:") || [
                      "clawsweeper:autofix",
                      "clawsweeper:automerge",
                      "clawsweeper:human-review",
                      "clawsweeper:manual-only",
                      "clawsweeper:bulk-filed",
                    ].includes(label);
                  }),
              ),
            ].sort();
            queueClaim.source_content_revision = crypto
              .createHash("sha256")
              .update(
                JSON.stringify({
                  version: 2,
                  title: source.title,
                  body: source.body || "",
                  locked: source.locked,
                  close_guard_labels: labels,
                }),
              )
              .digest("hex");
          }
          if (process.env.ITEM_KIND === "pull_request") {
            if (/^[0-9a-f]{40}$/.test(headSha)) queueClaim.source_head_sha = headSha;
            if (/^[0-9a-f]{40}$/.test(baseSha)) queueClaim.source_base_sha = baseSha;
            if (typeof pullRequest.draft === "boolean") {
              queueClaim.source_is_draft = pullRequest.draft;
            }
          }
          if (
            process.env.ITEM_KIND !== "pull_request" ||
            !/^[0-9a-f]{40}$/.test(headSha) ||
            !updatedAt
          ) {
            process.stdout.write(JSON.stringify(result));
          } else {
            result.ingress_route = "target_dispatcher";
            result.ingress_fingerprint = crypto
              .createHash("sha256")
              .update(
                JSON.stringify({
                  version: 1,
                  target_repo: String(process.env.TARGET_REPO || "").toLowerCase(),
                  item_number: Number(process.env.ITEM_NUMBER),
                  action: String(process.env.SOURCE_ACTION || ""),
                  head_sha: headSha,
                  updated_at: updatedAt,
                  body: typeof pullRequest.body === "string" ? pullRequest.body : "",
                  label: String(event.label?.name || ""),
                }),
              )
              .digest("hex");
            process.stdout.write(JSON.stringify(result));
          }
          NODE
          )"
          client_payload="$(jq -nc \
            --arg target_repo "$TARGET_REPO" \
            --arg target_branch "$TARGET_BRANCH" \
            --argjson item_number "$ITEM_NUMBER" \
            --arg item_kind "$ITEM_KIND" \
            --arg source_event "$SOURCE_EVENT" \
            --arg source_action "$SOURCE_ACTION" \
            --argjson source_identity "$source_identity_json" \
            --argjson supersedes_in_progress "$SUPERSEDES_IN_PROGRESS" \
            '{target_repo:$target_repo,target_branch:$target_branch,item_number:$item_number,item_kind:$item_kind,source_event:$source_event,source_action:$source_action,supersedes_in_progress:$supersedes_in_progress} + $source_identity')"
          # The App webhook remains an independent delivery route.
          if [ -n "${ACTIONS_ID_TOKEN_REQUEST_URL:-}" ] &&
            [ -n "${ACTIONS_ID_TOKEN_REQUEST_TOKEN:-}" ] &&
            oidc_token="$(curl --fail --silent --show-error --connect-timeout 5 --max-time 15 \
              --header "Authorization: bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN" \
              --get --data-urlencode "audience=$TARGET_DISPATCH_URL" \
              "$ACTIONS_ID_TOKEN_REQUEST_URL" | jq -er '.value | strings | select(length > 0)')" &&
            [ -n "$oidc_token" ]; then
            echo "::add-mask::$oidc_token"
            direct_body="$RUNNER_TEMP/clawsweeper-direct-intake.json"
            if direct_status="$(curl --silent --show-error --connect-timeout 5 --max-time 20 \
              --request POST \
              --header "authorization: Bearer $oidc_token" \
              --header "content-type: application/json" \
              --data "$client_payload" \
              --output "$direct_body" \
              --write-out '%{http_code}' \
              "$TARGET_DISPATCH_URL")" &&
              [[ "$direct_status" == 2[0-9][0-9] ]]; then
              echo "Queued ClawSweeper intake directly: $(jq -c . "$direct_body" 2>/dev/null || echo '{}')"
              exit 0
            fi
            # Only non-transient 4xx is a deliberate refusal; the App webhook covers it.
            # Timeouts, throttling, and verifier/Worker failures must stay re-runnable.
            if [[ "${direct_status:-}" == 4[0-9][0-9] && "$direct_status" != 408 && "$direct_status" != 429 ]]; then
              echo "::warning::ClawSweeper intake declined this event (HTTP $direct_status); the App webhook route still applies."
              exit 0
            fi
            echo "::error::ClawSweeper intake unavailable (HTTP ${direct_status:-none}); re-run this job after the Worker recovers."
          else
            echo "::error::ClawSweeper OIDC token unavailable; the dispatch job needs id-token: write."
          fi
          exit 1
      - name: Dispatch ClawSweeper comment
        if: >-
          ${{
            github.event_name == 'issue_comment' &&
            steps.comment_filter.outputs.is_command == 'true'
          }}
        env:
          TARGET_REPO: ${{ github.repository }}
          ITEM_NUMBER: ${{ github.event.issue.number }}
          COMMENT_ID: ${{ github.event.comment.id }}
          SOURCE_ACTION: ${{ github.event.action }}
          TARGET_DISPATCH_URL: https://clawsweeper.openclaw.ai/github/target-dispatch
        run: |
          set -euo pipefail
          client_payload="$(jq -nc \
            --arg target_repo "$TARGET_REPO" \
            --argjson item_number "$ITEM_NUMBER" \
            --argjson comment_id "$COMMENT_ID" \
            --arg source_action "$SOURCE_ACTION" \
            '{target_repo:$target_repo,item_number:$item_number,comment_id:$comment_id,source_event:"issue_comment",source_action:$source_action}')"
          # The App webhook remains an independent delivery route.
          if [ -n "${ACTIONS_ID_TOKEN_REQUEST_URL:-}" ] &&
            [ -n "${ACTIONS_ID_TOKEN_REQUEST_TOKEN:-}" ] &&
            oidc_token="$(curl --fail --silent --show-error --connect-timeout 5 --max-time 15 \
              --header "Authorization: bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN" \
              --get --data-urlencode "audience=$TARGET_DISPATCH_URL" \
              "$ACTIONS_ID_TOKEN_REQUEST_URL" | jq -er '.value | strings | select(length > 0)')" &&
            [ -n "$oidc_token" ]; then
            echo "::add-mask::$oidc_token"
            direct_body="$RUNNER_TEMP/clawsweeper-direct-intake.json"
            if direct_status="$(curl --silent --show-error --connect-timeout 5 --max-time 20 \
              --request POST \
              --header "authorization: Bearer $oidc_token" \
              --header "content-type: application/json" \
              --data "$client_payload" \
              --output "$direct_body" \
              --write-out '%{http_code}' \
              "$TARGET_DISPATCH_URL")" &&
              [[ "$direct_status" == 2[0-9][0-9] ]]; then
              echo "Queued ClawSweeper intake directly: $(jq -c . "$direct_body" 2>/dev/null || echo '{}')"
              exit 0
            fi
            # Only non-transient 4xx is a deliberate refusal; the App webhook covers it.
            # Timeouts, throttling, and verifier/Worker failures must stay re-runnable.
            if [[ "${direct_status:-}" == 4[0-9][0-9] && "$direct_status" != 408 && "$direct_status" != 429 ]]; then
              echo "::warning::ClawSweeper intake declined this event (HTTP $direct_status); the App webhook route still applies."
              exit 0
            fi
            echo "::error::ClawSweeper intake unavailable (HTTP ${direct_status:-none}); re-run this job after the Worker recovers."
          else
            echo "::error::ClawSweeper OIDC token unavailable; the dispatch job needs id-token: write."
          fi
          exit 1

package model

import (
	"path/filepath"
	"regexp"
	"strings"
	"unicode"
)

var slugDash = regexp.MustCompile(`-+`)

func Slug(name string) string {
	name = strings.TrimSpace(strings.ToLower(name))
	var b strings.Builder
	for _, r := range name {
		switch {
		case unicode.IsLetter(r), unicode.IsDigit(r):
			b.WriteRune(r)
		case unicode.IsSpace(r), r == '-', r == '_', r == '\'', r == '.':
			b.WriteByte('-')
		}
	}
	out := strings.Trim(slugDash.ReplaceAllString(b.String(), "-"), "-")
	if out == "" {
		return "person"
	}
	return out
}

func NormalizeEmail(email string) string {
	return strings.ToLower(strings.TrimSpace(email))
}

func NormalizePhone(phone string) string {
	var b strings.Builder
	for _, r := range phone {
		if r >= '0' && r <= '9' {
			b.WriteRune(r)
		}
	}
	out := b.String()
	out = strings.TrimPrefix(out, "00")
	return out
}

func NormalizeName(name string) string {
	return strings.Join(strings.Fields(strings.ToLower(strings.TrimSpace(name))), " ")
}

func PathSlug(path string) string {
	return filepath.Base(filepath.Dir(path))
}

package discrawl

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/openclaw/clawdex/internal/model"
)

type Adapter struct {
	DBPath string
	Binary string
}

type dmRow struct {
	ChannelID     string `json:"channel_id"`
	Name          string `json:"name"`
	Messages      int    `json:"messages"`
	FirstMessage  string `json:"first_message"`
	LastMessage   string `json:"last_message"`
	CounterpartID string `json:"counterpart_id"`
}

func (a Adapter) ListDMContacts(ctx context.Context, minMessages int) ([]model.SourceContact, error) {
	if minMessages < 1 {
		minMessages = 1
	}
	dbPath, err := resolveDBPath(a.DBPath)
	if err != nil {
		return nil, err
	}
	binary := strings.TrimSpace(a.Binary)
	if binary == "" {
		binary = "sqlite3"
	}
	query := fmt.Sprintf(dmQuery, minMessages)
	// #nosec G204 -- sqlite3 is a configured binary and all arguments are passed without a shell.
	cmd := exec.CommandContext(ctx, binary, "-json", "-readonly", dbPath, query)
	raw, err := cmd.Output()
	if err != nil {
		return nil, sqliteErr(err)
	}
	var rows []dmRow
	if len(strings.TrimSpace(string(raw))) == 0 {
		return nil, nil
	}
	if err := json.Unmarshal(raw, &rows); err != nil {
		return nil, err
	}
	out := make([]model.SourceContact, 0, len(rows))
	for _, row := range rows {
		name := strings.TrimSpace(row.Name)
		if name == "" || row.ChannelID == "" {
			continue
		}
		accounts := map[string][]string{"discord": {"channel:" + row.ChannelID}}
		if row.CounterpartID != "" {
			accounts["discord"] = append(accounts["discord"], "user:"+row.CounterpartID)
		}
		out = append(out, model.SourceContact{
			Source:     "discord",
			ExternalID: row.ChannelID,
			Name:       name,
			Tags:       []string{"discord", "dm"},
			Accounts:   accounts,
		})
	}
	return out, nil
}

func resolveDBPath(path string) (string, error) {
	if strings.TrimSpace(path) == "" {
		home, err := os.UserHomeDir()
		if err != nil {
			return "", err
		}
		path = filepath.Join(home, ".discrawl", "discrawl.db")
	}
	if strings.HasPrefix(path, "~/") {
		home, err := os.UserHomeDir()
		if err != nil {
			return "", err
		}
		path = filepath.Join(home, strings.TrimPrefix(path, "~/"))
	}
	return filepath.Abs(path)
}

func sqliteErr(err error) error {
	if exitErr, ok := errors.AsType[*exec.ExitError](err); ok {
		return fmt.Errorf("discrawl sqlite query: %s", strings.TrimSpace(string(exitErr.Stderr)))
	}
	return err
}

const dmQuery = `
with dm as (
  select
    c.id as channel_id,
    c.name as name,
    count(m.id) as messages,
    min(m.created_at) as first_message,
    max(m.created_at) as last_message
  from channels c
  join messages m on m.channel_id = c.id
  where c.guild_id = '@me' and c.kind = 'dm'
  group by c.id, c.name
  having count(m.id) > %d
),
self as (
  select m.author_id
  from channels c
  join messages m on m.channel_id = c.id
  where c.guild_id = '@me' and c.kind = 'dm' and m.author_id is not null
  group by m.author_id
  order by count(distinct c.id) desc, count(m.id) desc
  limit 1
),
author_counts as (
  select c.id as channel_id, m.author_id, count(m.id) as messages
  from channels c
  join messages m on m.channel_id = c.id
  where c.guild_id = '@me' and c.kind = 'dm' and m.author_id is not null
  group by c.id, m.author_id
)
select
  dm.channel_id,
  dm.name,
  dm.messages,
  dm.first_message,
  dm.last_message,
  coalesce((
    select ac.author_id
    from author_counts ac, self
    where ac.channel_id = dm.channel_id and ac.author_id <> self.author_id
    order by ac.messages desc
    limit 1
  ), '') as counterpart_id
from dm
order by dm.messages desc, lower(dm.name);
`

package cli

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"os/exec"
	"path/filepath"
	"slices"
	"strings"

	"github.com/openclaw/clawdex/internal/contactexport"
	"github.com/openclaw/clawdex/internal/model"
	"github.com/openclaw/crawlkit/control"
)

func readCrawlerContacts(ctx context.Context, binary string) (string, []model.SourceContact, error) {
	manifest, err := readCrawlerManifest(ctx, binary)
	if err != nil {
		return "", nil, err
	}
	command, ok := manifest.Commands["contact-export"]
	if !ok {
		return "", nil, fmt.Errorf("%s metadata does not advertise contact-export", binary)
	}
	if !command.JSON {
		return "", nil, fmt.Errorf("%s contact-export must advertise json output", binary)
	}
	if command.Mutates {
		return "", nil, fmt.Errorf("%s contact-export must be read-only", binary)
	}
	argv, err := contactExportArgv(binary, command.Argv)
	if err != nil {
		return "", nil, err
	}
	cmd := exec.CommandContext(ctx, argv[0], argv[1:]...) // #nosec G204 -- argv comes from the local crawler manifest and is executed without a shell.
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	data, err := cmd.Output()
	if err != nil {
		msg := strings.TrimSpace(stderr.String())
		if msg != "" {
			return "", nil, fmt.Errorf("%s contact-export failed: %w: %s", binary, err, msg)
		}
		return "", nil, fmt.Errorf("%s contact-export failed: %w", binary, err)
	}
	export, err := contactexport.Decode(bytes.NewReader(data))
	if err != nil {
		return "", nil, fmt.Errorf("%s contact-export decode failed: %w", binary, err)
	}
	source := strings.TrimSpace(manifest.ID)
	if source == "" {
		source = filepath.Base(binary)
	}
	return source, sourceContactsFromExport(source, export), nil
}

func contactExportArgv(binary string, advertised []string) ([]string, error) {
	if len(advertised) == 0 {
		return nil, fmt.Errorf("%s contact-export argv is empty", binary)
	}
	requestedName := filepath.Base(binary)
	advertisedName := filepath.Base(advertised[0])
	if requestedName != "" && advertisedName != "" && requestedName != advertisedName {
		return nil, fmt.Errorf("%s contact-export argv starts with %q, want %q", binary, advertised[0], requestedName)
	}
	if !slices.Contains(advertised, "--json") {
		return nil, fmt.Errorf("%s contact-export argv must include --json", binary)
	}
	argv := slices.Clone(advertised)
	argv[0] = binary
	return argv, nil
}

func readCrawlerManifest(ctx context.Context, binary string) (control.Manifest, error) {
	cmd := exec.CommandContext(ctx, binary, "--json", "metadata") // #nosec G204 -- binary is an explicit local crawler command.
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	data, err := cmd.Output()
	if err != nil {
		msg := strings.TrimSpace(stderr.String())
		if msg != "" {
			return control.Manifest{}, fmt.Errorf("%s metadata failed: %w: %s", binary, err, msg)
		}
		return control.Manifest{}, fmt.Errorf("%s metadata failed: %w", binary, err)
	}
	var manifest control.Manifest
	if err := json.Unmarshal(data, &manifest); err != nil {
		return control.Manifest{}, fmt.Errorf("%s metadata decode failed: %w", binary, err)
	}
	if strings.TrimSpace(manifest.SchemaVersion) != control.SchemaVersion {
		return control.Manifest{}, fmt.Errorf("%s metadata schema_version = %q, want %q", binary, manifest.SchemaVersion, control.SchemaVersion)
	}
	return manifest, nil
}

func sourceContactsFromExport(source string, export contactexport.ContactExport) []model.SourceContact {
	contacts := make([]model.SourceContact, 0, len(export.Contacts))
	for _, c := range export.Contacts {
		contact := model.SourceContact{Source: source, Name: c.DisplayName}
		for i, phone := range c.PhoneNumbers {
			contact.Phones = append(contact.Phones, model.ContactValue{Value: phone, Source: source, Primary: i == 0})
		}
		contacts = append(contacts, contact)
	}
	return contacts
}

